from ext import *
ext('c10_eng_ch11',[
C("🛍️","पॉलीथीन हमारे जीवन में",["दुकान से सब्ज़ी तक हर जगह","सस्ती, हल्की और मज़बूत","फिर भी बड़ी समस्या","एक बार इस्तेमाल, सदियों तक कचरा"],"पॉलीथीन आज हमारे जीवन में हर जगह है। दुकान से सब्ज़ी लाइए तो पॉलीथीन, दूध लाइए तो पॉलीथीन, चाय भी पॉलीथीन में मिल जाती है। यह हल्की है, सस्ती है और मज़बूत भी, इसलिए लोग इसका ख़ूब इस्तेमाल करते हैं। पर इसकी सबसे बड़ी समस्या है कि एक बार इस्तेमाल होने के बाद यह कचरा बनकर सैकड़ों साल तक ज़मीन में पड़ी रहती है। कवि ने इसी रोज़ की चीज़ को कविता का विषय बनाया है, और इसकी तुलना इंसान के मन की चोट से की है। यह तुलना बहुत गहरी और नई है।"),
C("⏳","पॉलीथीन कभी नहीं गलती",["मिट्टी में नहीं घुलती","सौ से पाँच सौ साल तक बनी रहती","पानी और ज़मीन को गंदा करती है","जलाने पर ज़हरीला धुआँ"],"कविता में कवि बार-बार कहते हैं कि पॉलीथीन कभी नहीं गलती। यह वैज्ञानिक तथ्य भी है। पॉलीथीन पेट्रोलियम से बनती है और मिट्टी के जीवाणु इसे नहीं खा पाते, इसलिए यह सैकड़ों साल तक वैसी की वैसी पड़ी रहती है। अगर इसे जलाया जाए, तो हवा में ज़हरीला धुआँ फैलता है, जो साँस के रोग पैदा करता है। और अगर ज़मीन में दबाया जाए, तो पानी का रिसाव रुक जाता है और खेत की उपज घटती है। इसलिए पॉलीथीन न गलती है, न मरती है, बस हर जगह परेशानी पैदा करती है।"),
C("💔","मन की चोट की तुलना",["पॉलीथीन की तरह चोट भी नहीं गलती","कड़वे शब्द वर्षों याद रहते हैं","घाव भर जाए, दर्द रह जाता है","इसलिए सोच-समझकर बोलें"],"अब कविता की सबसे गहरी बात समझिए। कवि पॉलीथीन की तुलना मन की चोट से करते हैं। जैसे पॉलीथीन मिट्टी में नहीं गलती, वैसे ही किसी के कड़वे शब्दों की चोट भी मन से नहीं मिटती। शरीर का घाव भर जाता है, पर शब्दों का घाव सालों तक याद रहता है। इसलिए हमें किसी से बात करते समय सोच-समझकर बोलना चाहिए। किसी को चिढ़ाना, ताना मारना या अपमान करना भी एक तरह का प्रदूषण है, जो इंसान के मन में रहकर उसे दुख देता है। यह दूसरा संदेश कविता को बहुत ख़ास बनाता है।"),
C("🎭","रूपक अलंकार",["एक चीज़ को दूसरी का रूप देना","पॉलीथीन ही मन की चोट है","इसमें जैसे या सा शब्द नहीं","भाव सीधे और गहरे उतरते हैं"],"इस कविता में रूपक अलंकार है। रूपक में एक चीज़ को सीधे दूसरी चीज़ का रूप दे दिया जाता है, बिना जैसे या सा शब्द लगाए। यहाँ पॉलीथीन को सीधे मन की चोट बना दिया गया है। उपमा और रूपक का यही फ़र्क़ है। उपमा में कहते हैं, चेहरा चाँद जैसा है। रूपक में कहते हैं, चेहरा चाँद है। अंग्रेज़ी में रूपक को मेटाफ़र कहते हैं और उपमा को सिमिली। परीक्षा में इनमें अंतर पूछा जा सकता है। इसलिए दोनों की परिभाषा और एक-एक उदाहरण याद कर लीजिए।"),
C("✍️","दुर्गा प्रसाद पंडा",["ओडिशा के कवि","ओड़िया और अंग्रेज़ी में लेखन","आधुनिक विषयों पर कविता","साधारण चीज़ों में गहरी बात"],"कवि दुर्गा प्रसाद पंडा ओडिशा के हैं। वे ओड़िया और अंग्रेज़ी, दोनों भाषाओं में लिखते हैं। उनकी ख़ासियत है कि वे आधुनिक जीवन की साधारण चीज़ों को कविता का विषय बना लेते हैं। जैसे यहाँ पॉलीथीन की थैली। आम तौर पर कवि चाँद, फूल या नदी पर लिखते हैं, पर पंडा ने कचरे में पड़ी चीज़ से गहरा संदेश निकाला। इसे कहते हैं नई दृष्टि। परीक्षा में कवि का नाम, राज्य और भाषा याद रखिए। और यह भी याद रखिए कि कविता हमारे आज के पर्यावरण संकट से जुड़ी है।"),
C("🌾","पर्यावरण पर असर",["खेत की उपजाऊ मिट्टी बिगड़ती है","नाले जाम, शहरों में जलभराव","पशु पन्नी खाकर बीमार","नदियाँ और तालाब गंदे"],"पॉलीथीन का पर्यावरण पर बहुत बुरा असर पड़ता है। खेतों में पड़ी पन्नी बारिश के पानी को ज़मीन में जाने से रोकती है और फ़सल की जड़ें कमज़ोर करती है। शहरों में नाले पन्नी से जाम हो जाते हैं और बारिश में पानी भर जाता है। गाय और बकरी जैसे जानवर खाने के साथ पन्नी भी निगल लेते हैं और बीमार पड़ जाते हैं। नदियों और तालाबों में बहकर पन्नी जलीय जीवों को भी नुकसान पहुँचाती है। यह सब देखते हुए पॉलीथीन का प्रयोग घटाना हम सबकी ज़िम्मेदारी है।"),
C("♻️","विकल्प क्या हैं",["कपड़े और जूट के थैले","काग़ज़ और पत्तों के दोने","स्टील के डिब्बे और बोतलें","री-यूज़ और रिसाइकल"],"अब सवाल है कि पॉलीथीन की जगह क्या इस्तेमाल करें। पहला विकल्प कपड़े या जूट के थैले हैं, जो बार-बार काम आते हैं। दूसरा, काग़ज़ के लिफ़ाफ़े और पत्तों के दोने-पत्तल, जो बिहार में पहले से प्रचलित हैं। तीसरा, घर से स्टील का डिब्बा या बोतल ले जाना। चौथा, अगर पॉलीथीन आ भी जाए, तो उसे फेंकने के बजाय दोबारा इस्तेमाल कीजिए और कचरे में बाक़ी प्लास्टिक से अलग रखिए। तीन आर याद रखिए, रिड्यूस यानी घटाओ, रीयूज़ यानी दोबारा उपयोग करो, रिसाइकल यानी पुनर्चक्रण।"),
C("📝","शब्दार्थ दोहराइए",["पॉलीथीन यानी प्लास्टिक की पन्नी","डिज़ॉल्व यानी घुलना","टॉक्सिक यानी ज़हरीला","गार्बेज और हर्ट"],"नए शब्द दोहराइए। पॉलीथीन यानी प्लास्टिक की पन्नी, डिज़ॉल्व यानी घुलना, हर्ट यानी चोट, टॉक्सिक यानी ज़हरीला और गार्बेज यानी कचरा। इनके साथ प्लास्टिक, पॉल्यूशन और एनवायरनमेंट भी याद कर लीजिए। एक अभ्यास कीजिए। हर शब्द से एक वाक्य बनाइए। जैसे पॉलीथीन डज़ नॉट डिज़ॉल्व इन सॉइल, यानी पॉलीथीन मिट्टी में नहीं घुलती। और बर्निंग पॉलीथीन रिलीज़ेज़ टॉक्सिक स्मोक, यानी जलती पॉलीथीन ज़हरीला धुआँ छोड़ती है। वाक्यों में प्रयोग से शब्द पक्के याद रहते हैं।"),
C("🔁","नेवर और ऑलवेज़ का प्रयोग",["नेवर यानी कभी नहीं","ऑलवेज़ यानी हमेशा","क्रिया से पहले आते हैं","आवृत्ति बताने वाले क्रिया-विशेषण"],"आज का व्याकरण नेवर और ऑलवेज़ है। ये आवृत्ति बताने वाले शब्द हैं, यानी कितनी बार कोई काम होता है। ऑलवेज़ का मतलब है हमेशा, यूज़्वली यानी आम तौर पर, समटाइम्स यानी कभी-कभी और नेवर यानी कभी नहीं। ये शब्द आम तौर पर मुख्य क्रिया से पहले आते हैं। जैसे आई ऑलवेज़ कैरी अ क्लॉथ बैग, यानी मैं हमेशा कपड़े का थैला रखता हूँ। पॉलीथीन नेवर डिज़ॉल्व्स, यानी पॉलीथीन कभी नहीं घुलती। अपनी दिनचर्या पर इन चारों शब्दों से चार वाक्य बनाइए।"),
C("🏞️","बिहार में प्लास्टिक पर रोक",["पतली पॉलीथीन पर प्रतिबंध","गंगा और तालाबों की सफ़ाई","छठ घाट पर सफ़ाई अभियान","हम सबका सहयोग ज़रूरी"],"बिहार सरकार ने पतली पॉलीथीन के उपयोग पर रोक लगाई है, और जल जीवन हरियाली अभियान के तहत तालाबों और नदियों की सफ़ाई पर भी ज़ोर दिया गया है। छठ पूजा से पहले हर साल घाटों की सफ़ाई की जाती है, ताकि पूजा पवित्र वातावरण में हो। पर क़ानून तभी सफल होता है जब हम सब उसका पालन करें। अगली बार हाट या बाज़ार जाइए तो अपना थैला साथ ले जाइए और दुकानदार से पन्नी माँगने की आदत छोड़िए। छोटा बदलाव मिलकर बड़ा फ़र्क़ ला सकता है।"),
C("🗣️","शब्दों की चोट",["ताने और चिढ़ाना भी हिंसा","माफ़ी माँगना बड़ी बात","मीठा बोलना सीखिए","अच्छे शब्द मरहम का काम करते हैं"],"कविता का दूसरा पहलू शब्दों की चोट है। स्कूल में हम कई बार अपने साथियों को नाम से चिढ़ाते हैं या मज़ाक उड़ाते हैं। हमें लगता है यह मज़ाक है, पर सामने वाले के मन पर चोट लग जाती है, जो लंबे समय तक रहती है। इसलिए पॉलीथीन की तरह ही बुरे शब्द भी कम से कम फेंकिए। अगर ग़लती से किसी को दुख पहुँचे, तो माफ़ी माँगना सीखिए। और अच्छे शब्द मरहम की तरह होते हैं। किसी की तारीफ़ कीजिए, किसी को हौसला दीजिए। इससे आपकी भी छवि अच्छी बनती है।"),
C("📌","पूरी कविता का सार",["पॉलीथीन कभी नहीं गलती","मन की चोट भी नहीं गलती","पर्यावरण और रिश्ते दोनों की सुरक्षा","दोनों संदेश याद रखिए"],"अंत में पूरी कविता का सार याद कर लीजिए। दुर्गा प्रसाद पंडा की कविता में पॉलीथीन की थैली की तुलना मन की चोट से की गई है। दोनों कभी नहीं गलतीं। पॉलीथीन पर्यावरण को नुकसान पहुँचाती है और कड़वे शब्द रिश्तों को। रूपक अलंकार और सरल भाषा कविता की ख़ूबी हैं। कविता के दो संदेश हैं, पहला पॉलीथीन का प्रयोग बंद कीजिए, और दूसरा किसी का दिल मत दुखाइए। इस सार को पाँच वाक्यों में अपनी भाषा में लिखकर अभ्यास कीजिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि कौन हैं","पॉलीथीन की तुलना किससे","पॉलीथीन के नुकसान गिनाइए","कविता का संदेश लिखिए"],"परीक्षा के प्रश्न देखिए। पहला, कवि कौन हैं? उत्तर, दुर्गा प्रसाद पंडा, ओडिशा के। दूसरा, पॉलीथीन की तुलना किससे की गई है? उत्तर, मन की चोट से, क्योंकि दोनों कभी नहीं मिटतीं। तीसरा, पॉलीथीन के नुकसान? उत्तर, मिट्टी बिगड़ती है, नाले जाम होते हैं, पशु बीमार होते हैं और जलाने पर ज़हरीला धुआँ निकलता है। चौथा, संदेश? उत्तर, पॉलीथीन छोड़ें और किसी का दिल न दुखाएँ। इन उत्तरों को पूरे वाक्य में लिखिए।"),
Q("आप अपने घर और गाँव में पॉलीथीन कम करने के लिए कौन से तीन काम कर सकते हैं?","कपड़े का थैला साथ रखना, पन्नी फेंकने के बजाय दोबारा काम में लेना और दूसरों को भी समझाना।","अब एक सोचने वाला प्रश्न। आप अपने घर और गाँव में पॉलीथीन कम करने के लिए कौन से तीन काम कर सकते हैं? सोचिए। ... कपड़े का थैला साथ रखना, पन्नी फेंकने के बजाय दोबारा काम में लेना, और दूसरों को भी इसके नुकसान समझाना। छोटे क़दम ही बड़ा बदलाव लाते हैं।"),
Q("कवि ने पॉलीथीन की तुलना मन की चोट से क्यों की?","क्योंकि दोनों कभी नहीं गलतीं और लंबे समय तक नुकसान पहुँचाती रहती हैं।","एक और प्रश्न। कवि ने पॉलीथीन की तुलना मन की चोट से क्यों की? सोचिए। ... क्योंकि दोनों कभी नहीं गलतीं और लंबे समय तक नुकसान पहुँचाती रहती हैं। पॉलीथीन पर्यावरण को, और चोट मन को। इसे पूरे वाक्य में कॉपी में लिखिए।"),
],7)
